range.exactText:
.page-guide > summary {
  position: relative;
  min-height: 72px;
  padding: 17px 56px 17px 20px;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.5;
  list-style: none;
  cursor: pointer;
}

.page-guide > summary::after {
  content: "";
  position: absolute;
  top: 30px;
  right: 24px;
  width: 10px;
  height: 10px;
  border-right: 2px solid var(--teal);
  border-bottom: 2px solid var(--teal);
  transform: rotate(45deg);
}

.page-guide > summary strong {
  display: block;
  color: var(--ink);
  font: 800 22px/1.25 "Hanken Grotesk", sans-serif;
}

.page-guide > summary strong::before {
  content: "Page guide";
  display: block;
  margin-bottom: 3px;
  color: var(--teal);
  font: 850 10px/1.4 "Work Sans", sans-serif;
  letter-spacing: .07em;
  text-transform: uppercase;
}

